package ru.neverland.mintexpeditions;
import org.bukkit.Material;import org.bukkit.entity.EntityType;import ru.neverland.mintexpeditions.model.*;import ru.neverland.mintexpeditions.service.SiteGenerator;import java.util.List;
public final class SiteGeneratorTest {public static void main(String[]args){for(ExpeditionType type:ExpeditionType.values()){ExpeditionDefinition d=new ExpeditionDefinition("test","Test",type,ObjectiveType.EXCAVATE,Material.STONE,0,1,60,1,2,8,type==ExpeditionType.SHIPWRECK?Material.BARREL:Material.AMETHYST_CLUSTER,EntityType.ZOMBIE,2,List.of(),List.of(),0,List.of());SitePlan p=new SiteGenerator().generate(d,new BlockPos(0,64,0));if(p.blocks().isEmpty()||p.objectives().size()!=8||!p.blocks().keySet().containsAll(p.objectives()))throw new AssertionError(type);System.out.println(type+": blocks="+p.blocks().size()+", objectives="+p.objectives().size());}}}
